import{_ as t,o as a,c as o,ah as n}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Grades and evaluations","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/enseignant/notes-et-evaluations.md","filePath":"src/en/guide/enseignant/notes-et-evaluations.md"}'),s={name:"en/guide/enseignant/notes-et-evaluations.md"};function r(i,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="grades-and-evaluations" tabindex="-1">Grades and evaluations <a class="header-anchor" href="#grades-and-evaluations" aria-label="Permalink to &quot;Grades and evaluations&quot;">​</a></h1><p>This page covers creating an evaluation and entering the grades attached to it. If your school grades some classes by competency rather than by numeric score (typically nursery/pre-school), the last section explains how to record your observations there.</p><h2 id="create-an-evaluation" tabindex="-1">Create an evaluation <a class="header-anchor" href="#create-an-evaluation" aria-label="Permalink to &quot;Create an evaluation&quot;">​</a></h2><ol><li>Open <strong>Teaching → Evaluations</strong> in the menu.</li><li>Click <strong>New evaluation</strong>.</li><li>In the <strong>Context</strong> section, choose the <strong>Class</strong>, <strong>Subject</strong>, <strong>Academic period</strong> and <strong>Evaluation type</strong> — all four lists only offer your own class/subject assignments.</li><li>In the <strong>Details</strong> section, fill in the evaluation&#39;s <strong>Label</strong>, its <strong>Max score</strong> (20 by default, editable) and its <strong>Date</strong>.</li><li>Click <strong>Save</strong>.</li></ol><h2 id="find-an-evaluation" tabindex="-1">Find an evaluation <a class="header-anchor" href="#find-an-evaluation" aria-label="Permalink to &quot;Find an evaluation&quot;">​</a></h2><p>On the <strong>Evaluations</strong> page, use the search field (by label) and the class filter to find an evaluation in the list, which shows each one&#39;s class, subject, period and date. Clicking a row opens a detail panel.</p><h2 id="enter-grades" tabindex="-1">Enter grades <a class="header-anchor" href="#enter-grades" aria-label="Permalink to &quot;Enter grades&quot;">​</a></h2><ol><li>From the evaluations list, click <strong>Grades</strong> on the row for the relevant evaluation. At the top of the page, the <strong>Out of…</strong> chip shows the scale, which is also shown inside every score field.</li><li>For each student, enter their <strong>Score</strong> and, if applicable, a <strong>Bonus/malus</strong>. Decimals can be typed with a comma or a dot. The <strong>Enter</strong> key moves straight to the next student&#39;s score, like a spreadsheet.</li><li>One click changes the <strong>Status</strong>: <strong>Graded</strong>, <strong>Absent</strong> or <strong>Excused</strong>. An absent or excused student has no score: their fields are disabled. The <strong>Current subject average</strong> column shows each student&#39;s average in the subject before you save.</li><li>The bar at the bottom shows how many grades are entered (for example &quot;24/30 grades entered&quot;) and flags unsaved changes. Click <strong>Save</strong>: every row is saved at once.</li></ol><p>Every <strong>Graded</strong> student needs a score. If any is missing, nothing is saved: the bottom bar shows how many fields to fix and the page takes you to the first one. If you leave the page before saving, ERA asks you to confirm so you don&#39;t lose what you entered.</p><h2 id="edit-or-delete-an-evaluation" tabindex="-1">Edit or delete an evaluation <a class="header-anchor" href="#edit-or-delete-an-evaluation" aria-label="Permalink to &quot;Edit or delete an evaluation&quot;">​</a></h2><p>From the list, use <strong>Edit</strong> to change an evaluation&#39;s context or details. <strong>Delete</strong> permanently removes it along with <strong>every grade recorded for it</strong> — a confirmation dialog asks you to confirm before this irreversible action runs.</p><h2 id="competency-observations" tabindex="-1">Competency observations <a class="header-anchor" href="#competency-observations" aria-label="Permalink to &quot;Competency observations&quot;">​</a></h2><p>Some departments — typically nursery and pre-school — are graded by competency rather than by numeric score: the teacher is assigned to the whole class there, with no separate subject, and the administrator defines a list of competencies to observe (admin menu <strong>School setup → Competencies</strong>). If one of your classes belongs to such a department, a <strong>Competency observations</strong> page is available for it.</p><ol><li>Open the <strong>Competency observations</strong> page for the relevant class.</li><li>Choose the <strong>academic period</strong> from the selector at the top of the page — the list of students and competencies reloads automatically.</li><li>For each student and each competency, choose a level: <strong>Not acquired</strong>, <strong>In progress</strong> or <strong>Acquired</strong>, and optionally add a comment. Each student has their own card, with one line per competency.</li><li>Click <strong>Save</strong>.</li></ol><p>A level is required for <strong>every</strong> competency of <strong>every</strong> student: if one is missing, nothing is saved, a message says so above the list and the levels still to fill in are outlined in red.</p><p>If the class&#39;s department has no competencies defined yet, the page shows &quot;This department has no competencies to observe&quot; — an administrator needs to create some before you can record anything.</p>',16)])])}const p=t(s,[["render",r]]);export{u as __pageData,p as default};
